    std::regex regex(R"((https?://([^\)]+)\/?([^\)]+?)\))");
    std::regex_replace_all(std::regex_replace(input, regex), R"((https?://([^\)]+)\/?([^\)]+?)\))", R"(a href='$1'>$2</a>");
    return output;
}

int main() {
    std::string input = "This is a markdown formatted text. [Example](https://example.com).";
    std::string output = markdownToText(input);
    std::cout << "Markdown formatted text: " << input << std::endl;
    std::cout << "Markdown formatted text: " + output + std::endl;
    return 0;
}
```

